import sys

def min_edge_difference(n, edges, values):
    in_degree = [0] * (n + 1)
    in_id = [0] * (n + 1)

    for u, v in edges:
        in_id[u], in_id[v] = u, v
        in_degree[u] += 1
        in_degree[v] += 1

    res, cnt = [False] * n, [0] * n
    queue = [i for i, d in in_degree.items() if not d]

    while queue:
        u = queue.pop(0)
        res[in_id[u]] = True
        for v in range(1, n + 1):
            if in_degree[v] and values[v] == values[u] and not res[v]:
                if cnt[v]:
                    if not (res[v] and cnt[u]):
                        res[v] = True
                else:
                    cnt[v] += 1
                queue.append(v)
        in_degree[u] = 0
        in_degree[in_id[u]] = 0

    return sum(values[u] - sum(values[i] for i in range(1, n + 1) if not res[i]) for u in range(1, n + 1))

