import math

def max_folds(sequence):
    n = len(sequence)
    dp = [0] * n
    orig_sequence = [0] * n

    for i in range(1, n):
        for j in range(i):
            if sequence[i] == sequence[j] and dp[i] < dp[j] + (sequence[i] != 0):
                dp[i] = dp[j] + (sequence[i] != 0)
                orig_sequence[i] = (orig_sequence[j] + 1) % 2

