        for x, y in chair_distances:
            if x < chair_distances[0][0] and y > chair_distances[0][0]:
                enqueued.append((x - chair_distances[0][0] + a[0], chair_distances[0][1] - chair_distances[0][0]))
            elif x == chair_distances[0][0]:
                break

        # Dequeue all large chairs to the right of the current girl's chair
        for x, y in reversed(chair_distances):
            if x > chair_distances[-1][0] and y < chair_distances[-1][0]:
                dequeued.append((x - chair_distances[-1][0] + d[-1], chair_distances[-1][1] - chair_distances[-1][0]))
            elif x == chair_distances[-1][0]:
                break

        chair_distances.extend(list(heapq.merge(enqueued, dequeued)))
        chair_distances = list(set(chair_distances))

    # Calculate total time
    time = sum(abs(xi - xj) + a[i] + b[j] for i, xj in enumerate(chair_distances) for j in range(i + 1, len(chair_distances)))
