from collections import deque, defaultdict

def cyclic_shift(grid, starting_cycle, destination_row, destination_col):
    # Flatten the grid into a list of numbers
    num_grid = ''.join(str(item) for sublist in grid for item in sublist)
    # Reverse the starting cycle
    reversed_cycle = destination_row == starting_cycle[0] and destination_col == starting_cycle[1]
    # Create a reversed cycle
    if reversed_cycle:
        reversed_cycle = deque(islice(tee(starting_cycle, destination_col - 1), destination_col - 1))
    else:
        reversed_cycle = deque(starmap(rotate_right, islice((starting_cycle,), destination_col - 1)))
    # Create a new grid with the reversed cycle applied
    new_grid = [str(item) for sublist in grid for item in sublist]
    # Reverse the reversed cycle
    if reversed_cycle:
        reversed_cycle = deque(reversed(islice(reversed_cycle, destination_col - 1)))
    else:
        reversed_cycle = deque(reversed(starmap(rotate_right, islice((starting_cycle,), destination_col - 1))))
    # Flatten the new grid into a number
    return ''.join(map(int, new_grid))

def rotate_right(cell):
    return (cell // m, cell % m)

def main(n, m, grid):
    starting_cycles = []
    for i in range(m):
        for j in range(m - 3):
            starting_cycles.append((i, j))

    total_op_count, solution = 0, defaultdict(list)

    while True:
        best_op_count, best_solution_cycle = float('inf'), None
        for starting_cycle_count in [4, 5]:
            cycle = tuple(starting_cycles) * starting_cycles.count(starting_cycle_count)
            for cycle in islice(tee(cycle, n // starting_cycle_count), n // starting_cycle_count):
                for destination_row, destination_col in zip(*[islice(cycle, None, 2), islice(cycle, 1, None)]):
                    op_count, solution_cycle = cyclic_shift(grid, tuple(cycle), destination_row, destination_col)
                    if op_count < best_op_count or (op_count == best_op_count and solution_cycle <= best_solution_cycle):
                        best_op_count, best_solution_cycle = op_count, solution_cycle
        solution[min(best_op_count, starting_cycles.count(4))] = best_solution_cycle
        total_op_count += best_op_count
        if total_op_count <= 100000:
            break
    print(str(len(solution.keys())) + ' ' + str(solution[min(solution.keys())]))

