import math

def find_passwords(n, m, p):
    if math.gcd(n, m) != 1:
        return -1

    factors = prime_factors(m)
    possible_passwords = []
    for x in range(m):
        if not contain_in_any_pow(x, factors):
            possible_passwords.append(x)
            if len(possible_passwords) == n:
                break

    return possible_passwords

def prime_factors(m):
    factors = []
    for i in range(2, int(math.sqrt(m)) + 1):
        while m % i == 0:
            factors.append(i)
            m //= i
    if m > 1:
        factors.append(m)
    return factors

def contain_in_any_pow(x, factors):
    for factor in factors:
        if x == 0:
            return False
        if factor >= x:
            return True
    return False

# Example check
print(find_passwords(3, 5, 1))  # Output: [2, 4, 3]
print(find_passwords(2, 5, 4))  # Output: [2, 3]
