import sys
from collections import deque

def build_dfs_graph(n, a):
    graph = [[] for _ in range(n+1)]
    for i in range(1, n+1):
        graph[0].append(i)
    for i, num in enumerate(a):
        for _ in range(num):
            graph[i].append(i+1)
            graph[i].append(i+1)
    return graph

def get_folds(graph, idx, visited):
    total_folds = 0
    for neighbor in graph[idx]:
        if neighbor not in visited:
            visited.add(neighbor)
            total_folds += get_folds(graph, neighbor, visited)
    return total_folds + 1

def process_sequence(n, a):
    graph = build_dfs_graph(n, a)
    max_folds = 0
    q = deque([(0, 0, set())])
    while q:
        u, distance, visited = q.popleft()
        if distance > max_folds:
            max_folds = distance
        for neighbor in graph[u]:
            if neighbor not in visited:
                visited.add(neighbor)
                q.append((neighbor, distance + 1, visited))
    return max_folds

def prepare_folds(n, a):
    result = [0] * (n+1)
    for i in range(1, n+1):
        result[i] = process_sequence(n, a)[0]
    return result[1:]

if __name__ == "__main__":
    n = int(input().strip())
    a = list(map(int, input().strip().split()))
    folds = prepare_folds(n, a)
    for fold in folds:
        print(fold)
