def bfs(start, deg, opposite):
    level = [-1] * N
    queue = [start]
    level[start] = 0
    while queue:
        nextlvl = []
        for u in queue:
            for v in range(N):
                if opp[u][v] and not level[v]:
                    level[v] = level[u] + 1
                    nextlvl.append(v)
        queue = nextlvl
    return level

def shortest_path(start, end, deg, opp):
    level = bfs(start, deg, opp)
    return -level[end] - 1 if end in range(len(level)) else -1

def is_vision(graph, start, end, goal, degree, level, path):
    if shortest_path(start, end, degree, path):
        new_path = [i for i in path]
        while shortest_path(end, goal, degree, new_path) and len(new_path) > goal:
            new_path.pop(0)
        if shortest_path(start, end, degree, new_path):
            return True
    return False

def find_zombie_paths(graph):
    N, M = len(graph), len(graph[0])
    degree = preprocess(graph)
    opposite = [[False] * N for _ in range(N)]
    for i in range(N):
        opposite[degree[i]][i] = True
    path_count = 0
    result = []
    for goal in range(1, 2 * N + 1):
        vis = [True] + [False] * N
        for k in range(goal // 2 + 1):
            new_graph = [set() for _ in range(N)]
            low_path = -k - 1 if goal % 2 else -k
            for i in range(low_path - 1):
                path = [i + 1]
                for j in range(i, low_path):
                    xi, yi, ki, v = graph[path[-1]][path[-2]]
                    if v == goal and is_vision(graph, path[-1], yi, yi, degree, level, path) and xi not in path:
                        vis[path[-1]] = False
                        new_graph[path[-1]].update([xi])
                        new_graph[xi].update([yi])
                        vis[yi] = False
                        path.append(yi)
                    elif k < len(graph) - 1 and len(graph) - 1 == k:
                        path.append(yi)
                if len(graph) - 1 != k:
                    path.pop(-1)
            graph = new_graph
            goal = k * 2
        if False in vis:
            level = bfs(range(len(vis)), degree, opposite)
            if shortest_path(range(len(vis)), -1) and ((min(level) + high > low) != vis[len(vis) - 1]):
                path_count += 1
                result.append([i + 1 for i in path[::-1]])

    return path_count % 1000000007, result

def get_input():
    N, M = map(int, input().split())
    graph = [[tuple(map(int, input().split())) for _ in range(2)] for _ in range(N)]
    return [N], [graph]

def main():
    [N, M], graph = get_input()
    path_count, paths = find_zombie_paths(graph)
    print(path_count)
    for path in paths:
        print(*path)

if __name__ == '__main__':
