        self.covers = set()
        self.is_reachable = {}

    def union(self, node_a, node_b):
        self.is_reachable[node_a] |= self.is_reachable[node_b]
        for neighbor in self.is_reachable[node_b]:
            self.is_reachable[neighbor].add(node_a)

