def min_time_to_cross(chairs, start, end):
    n = len(chairs)
    cost = [0] * n
    visited = [False] * n
    priority_queue = [(-cost[-1], -end, -start)]

    while priority_queue:
        cost, i, j = heappop(priority_queue)
        if not visited[i]:
            visited[i] = True
            if i == start:
                return -cost[-1]
            for k in range(i+1, n):
                if not visited[k]:
                    heappush(priority_queue, (cost + abs(chairs[i] - chairs[k]) + total[start][k], k, i))

            for k in range(i-1, -1, -1):
                if not visited[k]:
                    heappush(priority_queue, (cost + abs(chairs[k] - chairs[i]) + total[end][k], k, i))

            for k in range(1, i):
