def find_passwords(n, m, p):
    # Find the smallest prime factor of m
    for i in range(2, m):
        if m % i == 0:
            factor = i
            break
    # Iterate over all possible values of p that are not multiples of factor
    for k in range(1, m // factor + 1):
        if gcd(k, m) != 1:
            p *= k
            if p > m:
                p /= k
            break
    # If no valid p is found, print -1
    if p > m:
        return -1
    # Find all possible passwords
    passwords = set()
    for i in range(n):
        if gcd(i, m) != 1 and not any((p / i)**k == m for k in range(1, m // factor + 1)):
            passwords.add(i)
    return list(passwords)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

